-- Reporte consolidado de diferencias mensuales de nómina.
create or replace function public.list_hr_payroll_monthly_comparison(p_token text,p_year integer,p_month integer)
returns jsonb language plpgsql security definer set search_path=public,extensions as $$
declare v_user public.app_users;v_current_start date:=make_date(p_year,p_month,1);v_previous_start date:=(make_date(p_year,p_month,1)-interval '1 month')::date;
begin
 v_user:=public.hr_authenticated_user(p_token);
 if v_user.id is null or (v_user.role<>'Administrador' and not coalesce((v_user.permissions->>'ver_recursos_humanos')::boolean,false)) then return jsonb_build_object('success',false,'error','No posee permiso para consultar comparaciones de nómina.');end if;
 return jsonb_build_object('success',true,'period',to_char(v_current_start,'YYYY-MM'),'previous_period',to_char(v_previous_start,'YYYY-MM'),
 'summary',(with c as(select count(distinct l.employee_id) employees,coalesce(sum(l.gross_salary),0) gross,coalesce(sum(l.net_amount),0) net from public.hr_payroll_batch_lines l join public.hr_payroll_batches b on b.id=l.batch_id where b.payroll_year=p_year and b.payroll_month=p_month),p as(select count(distinct l.employee_id) employees,coalesce(sum(l.gross_salary),0) gross,coalesce(sum(l.net_amount),0) net from public.hr_payroll_batch_lines l join public.hr_payroll_batches b on b.id=l.batch_id where b.payroll_year=extract(year from v_previous_start)::integer and b.payroll_month=extract(month from v_previous_start)::integer) select jsonb_build_object('current_employees',c.employees,'previous_employees',p.employees,'current_gross',c.gross,'previous_gross',p.gross,'current_net',c.net,'previous_net',p.net,'gross_difference',c.gross-p.gross,'net_difference',c.net-p.net) from c cross join p),
 'employee_changes',coalesce((with c as(select l.employee_id,max(l.employee_name) employee_name,sum(l.gross_salary) gross,sum(l.net_amount) net,sum(l.other_deductions) deductions from public.hr_payroll_batch_lines l join public.hr_payroll_batches b on b.id=l.batch_id where b.payroll_year=p_year and b.payroll_month=p_month group by l.employee_id),p as(select l.employee_id,max(l.employee_name) employee_name,sum(l.gross_salary) gross,sum(l.net_amount) net,sum(l.other_deductions) deductions from public.hr_payroll_batch_lines l join public.hr_payroll_batches b on b.id=l.batch_id where b.payroll_year=extract(year from v_previous_start)::integer and b.payroll_month=extract(month from v_previous_start)::integer group by l.employee_id),x as(select coalesce(c.employee_id,p.employee_id) employee_id,coalesce(c.employee_name,p.employee_name) employee_name,case when p.employee_id is null then 'NUEVO' when c.employee_id is null then 'RETIRADO' when c.gross>p.gross then 'AUMENTO' when c.gross<p.gross then 'REDUCCION' when c.deductions>p.deductions then 'NUEVO_DESCUENTO' else 'VARIACION' end change_type,coalesce(c.gross,0) current_gross,coalesce(p.gross,0) previous_gross,coalesce(c.net,0) current_net,coalesce(p.net,0) previous_net,coalesce(c.deductions,0) current_deductions,coalesce(p.deductions,0) previous_deductions from c full join p using(employee_id) where c.employee_id is null or p.employee_id is null or c.gross<>p.gross or c.net<>p.net or c.deductions<>p.deductions) select jsonb_agg(to_jsonb(x) order by change_type,employee_name) from x),'[]'::jsonb),
 'classification_variations',coalesce((with c as(select l.execution_fund,l.program,l.activity,count(distinct l.employee_id) employees,sum(l.gross_salary) gross,sum(l.net_amount) net from public.hr_payroll_batch_lines l join public.hr_payroll_batches b on b.id=l.batch_id where b.payroll_year=p_year and b.payroll_month=p_month group by l.execution_fund,l.program,l.activity),p as(select l.execution_fund,l.program,l.activity,count(distinct l.employee_id) employees,sum(l.gross_salary) gross,sum(l.net_amount) net from public.hr_payroll_batch_lines l join public.hr_payroll_batches b on b.id=l.batch_id where b.payroll_year=extract(year from v_previous_start)::integer and b.payroll_month=extract(month from v_previous_start)::integer group by l.execution_fund,l.program,l.activity),x as(select coalesce(c.execution_fund,p.execution_fund) execution_fund,coalesce(c.program,p.program) program,coalesce(c.activity,p.activity) activity,coalesce(c.employees,0) current_employees,coalesce(p.employees,0) previous_employees,coalesce(c.gross,0) current_gross,coalesce(p.gross,0) previous_gross,coalesce(c.net,0) current_net,coalesce(p.net,0) previous_net from c full join p using(execution_fund,program,activity)) select jsonb_agg(to_jsonb(x) order by execution_fund,program,activity) from x),'[]'::jsonb),
 'anomalies',coalesce((select jsonb_agg(to_jsonb(x) order by x.severity,x.employee_name) from(
  select 'ERROR' severity,'PAGO_DUPLICADO' anomaly_type,l.employee_id,max(l.employee_name) employee_name,'El empleado aparece más de una vez en el mismo tipo de nómina.' message,count(*)::integer occurrences,string_agg(distinct b.payroll_type,', ') payroll_types from public.hr_payroll_batch_lines l join public.hr_payroll_batches b on b.id=l.batch_id where b.payroll_year=p_year and b.payroll_month=p_month group by l.employee_id,b.payroll_type having count(*)>1
  union all select 'ADVERTENCIA','MULTIPLES_NOMINAS',l.employee_id,max(l.employee_name),'El empleado está presente en más de un tipo de nómina.',count(distinct b.payroll_type)::integer,string_agg(distinct b.payroll_type,', ' order by b.payroll_type) from public.hr_payroll_batch_lines l join public.hr_payroll_batches b on b.id=l.batch_id where b.payroll_year=p_year and b.payroll_month=p_month group by l.employee_id having count(distinct b.payroll_type)>1
  union all select 'ERROR','SIN_CUENTA_PRESUPUESTARIA',l.employee_id,l.employee_name,'Registro sin cuenta presupuestaria.',1,b.payroll_type from public.hr_payroll_batch_lines l join public.hr_payroll_batches b on b.id=l.batch_id where b.payroll_year=p_year and b.payroll_month=p_month and nullif(trim(l.account_code),'') is null
 )x),'[]'::jsonb));
end $$;
grant execute on function public.list_hr_payroll_monthly_comparison(text,integer,integer) to anon,authenticated;
